**구현된 MVP 기능**
1. **추가·삭제**: 입력창에 쓰고 Enter 또는 "추가" 버튼으로 추가하고, 각 항목의 "삭제" 버튼으로 지웁니다.
2. **완료 토글**: 체크박스를 누르면 완료 상태가 바뀌고, 완료된 항목에는 취소선이 표시됩니다.
3. **로컬스토리지 자동 저장**: 추가·삭제·토글 때마다 `localStorage`에 저장하고, 페이지를 열 때 불러옵니다.

범위 외로 지정된 카테고리, 필터, 검색, 반복 일정, 계정, 동기화는 넣지 않았습니다. 실행 환경이 없어 브라우저에서 직접 동작을 확인하지는 못했습니다.

**변경 요약:** 지원 카테고리를 거리·무게·온도로 명시했고, 웹/CLI 중 기본값으로 웹을 택했으며, MVP 범위를 양방향(단일 쌍) 변환으로 한정했습니다.

웹과 CLI 중 선택 기준이 따로 없어서 웹으로 진행했습니다. CLI가 더 필요하면 변환 로직(`convert`)을 그대로 재사용할 수 있습니다. 이 환경에서는 파일을 만들거나 실행할 수 없어 코드를 응답에 직접 적었습니다. 아래 `unit-converter.html`로 저장해서 브라우저로 열면 됩니다.

```html
<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>단위 변환기</title>
<style>
  body { font-family: system-ui, sans-serif; background: #f4f5f7; margin: 0; padding: 2rem 1rem; }
  main { max-width: 480px; margin: 0 auto; background: #fff; padding: 1.5rem; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,.08); }
  h1 { margin-top: 0; font-size: 1.4rem; }
  label { display: block; font-size: .85rem; color: #555; margin: 1rem 0 .3rem; }
  select, input { width: 100%; box-sizing: border-box; padding: .6rem; font-size: 1rem; border: 1px solid #ccc; border-radius: 8px; }
  input.invalid { border-color: #d93025; }
  .row { display: flex; gap: .5rem; align-items: end; }
  .row > div { flex: 1; }
  #swap { width: auto; padding: .6rem .9rem; cursor: pointer; background: #eef; }
  #warning { min-height: 1.3rem; margin-top: 1rem; color: #d93025; font-size: .9rem; }
  #result { margin-top: .5rem; font-size: 1.6rem; font-weight: 600; word-break: break-all; }
</style>
</head>
<body>
<main>
  <h1>단위 변환기</h1>

  <label for="category">카테고리</label>
  <select id="category"></select>

  <label for="value">값</label>
  <input id="value" type="text" inputmode="decimal" placeholder="예: 100" autocomplete="off" value="1">

  <div class="row">
    <div>
      <label for="from">변환 전 단위</label>
      <select id="from"></select>
    </div>
    <button id="swap" type="button" title="단위 바꾸기" aria-label="단위 바꾸기">⇄</button>
    <div>
      <label for="to">변환 후 단위</label>
      <select id="to"></select>
    </div>
  </div>

  <div id="warning" role="alert"></div>
  <div id="result" aria-live="polite"></div>
</main>

<script>
// 거리는 m, 무게는 g를 기준 단위로 삼아 변환한다.
const CATEGORIES = {
  length: {
    label: '거리',
    factors: { mm: 0.001, cm: 0.01, m: 1, km: 1000, inch: 0.0254, ft: 0.3048, mile: 1609.344 },
  },
  mass: {
    label: '무게',
    factors: { g: 1, kg: 1000, lb: 453.59237, oz: 28.349523125 },
  },
  temperature: {
    label: '온도',
    units: ['°C', '°F', 'K'],
  },
};

const toCelsius   = { '°C': v => v, '°F': v => (v - 32) * 5 / 9, 'K': v => v - 273.15 };
const fromCelsius = { '°C': c => c, '°F': c => c * 9 / 5 + 32,   'K': c => c + 273.15 };

function unitsOf(catKey) {
  const c = CATEGORIES[catKey];
  return c.units ?? Object.keys(c.factors);
}

// 변환 로직. 입력이 올바르다고 가정한다 (검증은 validate에서 한다).
function convert(catKey, value, from, to) {
  if (catKey === 'temperature') {
    return fromCelsius[to](toCelsius[from](value));
  }
  const f = CATEGORIES[catKey].factors;
  return value * f[from] / f[to];
}

// 문제가 있으면 경고 문자열을, 없으면 null을 반환한다.
function validate(catKey, raw) {
  const text = raw.trim();
  if (text === '') return '값을 입력하세요.';
  const n = Number(text);
  if (Number.isNaN(n)) return '숫자만 입력할 수 있습니다.';
  if (!Number.isFinite(n)) return '값이 너무 큽니다.';
  if (catKey !== 'temperature' && n < 0) return '거리와 무게는 0 이상이어야 합니다.';
  return null;
}

function checkTemperatureRange(value, from) {
  if (toCelsius[from](value) < -273.15 - 1e-9) return '절대영도(-273.15°C) 아래의 온도는 존재하지 않습니다.';
  return null;
}

function format(n) {
  if (Object.is(n, -0)) n = 0;
  const r = parseFloat(n.toPrecision(12)); // 부동소수점 오차 제거
  if (r !== 0 && (Math.abs(r) >= 1e15 || Math.abs(r) < 1e-6)) return r.toExponential();
  return r.toLocaleString('en-US', { maximumFractionDigits: 12 });
}

const $ = id => document.getElementById(id);
const catEl = $('category'), valEl = $('value'), fromEl = $('from'), toEl = $('to');
const warnEl = $('warning'), resEl = $('result');

function fillUnits() {
  const units = unitsOf(catEl.value);
  for (const el of [fromEl, toEl]) {
    el.innerHTML = units.map(u => `<option value="${u}">${u}</option>`).join('');
  }
  fromEl.value = units[0];
  toEl.value = units[1];
}

function update() {
  const cat = catEl.value, from = fromEl.value, to = toEl.value;
  let warning = validate(cat, valEl.value);
  let value = warning ? null : Number(valEl.value.trim());

  if (!warning && cat === 'temperature') warning = checkTemperatureRange(value, from);

  if (!warning) {
    const out = convert(cat, value, from, to);
    if (!Number.isFinite(out)) warning = '결과가 표현 범위를 벗어났습니다.';
    else resEl.textContent = `${format(value)} ${from} = ${format(out)} ${to}`;
  }

  valEl.classList.toggle('invalid', Boolean(warning));
  warnEl.textContent = warning ?? '';
  if (warning) resEl.textContent = '';
}

catEl.innerHTML = Object.entries(CATEGORIES)
  .map(([k, c]) => `<option value="${k}">${c.label}</option>`).join('');

catEl.addEventListener('change', () => { fillUnits(); update(); });
valEl.addEventListener('input', update);
fromEl.addEventListener('change', update);
toEl.addEventListener('change', update);
$('swap').addEventListener('click', () => {
  [fromEl.value, toEl.value] = [toEl.value, fromEl.value];
  update();
});

fillUnits();
update();
</script>
</body>
</html>
```

## 동작 요약

- **카테고리·단위**
  - 거리: mm, cm, m, km, inch, ft, mile
  - 무게: g, kg, lb, oz
  - 온도: °C, °F, K
- **변환 방식:** 변환 전/후 단위 한 쌍만 선택하며, `⇄` 버튼으로 두 단위를 바꿀 수 있습니다. 입력하면 바로 결과가 갱신됩니다.
- **경고 표시:** 빈 값, 숫자가 아닌 입력, 너무 큰 값(`1e999`), 거리·무게의 음수, 절대영도 미만 온도에 빨간 경고를 띄웁니다.
- **부동소수점 오차:** 12자리 유효숫자로 정리해서 `0.30000000000000004` 같은 값이 나오지 않게 했습니다.

## 직접 확인할 기준값

아래 값은 계산식으로 손으로 검증한 것이고, 코드를 실제로 실행해 본 것은 아닙니다.

| 입력 | 기대 결과 |
|---|---|
| 1 mile → m | 1,609.344 |
| 1 inch → cm | 2.54 |
| 1 ft → inch | 12 |
| 1 lb → g | 453.59237 |
| 16 oz → lb | 1 |
| 100 °C → °F | 212 |
| 0 K → °C | -273.15 |
| -500 °C | 절대영도 경고 |
| `abc` | 숫자 경고 |

## 확인이 필요한 부분

- 거리·무게의 음수를 경고로 처리했습니다. 음수도 허용하려면 `validate`의 해당 줄을 지우면 됩니다.
- 웹 대신 CLI를 원하시면 알려주세요. `convert`와 `validate`를 Node.js나 Python 스크립트로 옮겨 드리겠습니다.

