**`unit_converter.py`**

```python
#!/usr/bin/env python3
"""단위 변환기 (표준 라이브러리만 사용).

사용 예:
    python unit_converter.py 10 km mi
    python unit_converter.py 100 c f
    python unit_converter.py --list
"""
from __future__ import annotations

import argparse
import sys

# 카테고리별 {단위: 기준 단위 대비 배율}
LINEAR: dict[str, dict[str, float]] = {
    "길이(기준 m)": {
        "mm": 0.001, "cm": 0.01, "m": 1.0, "km": 1000.0,
        "in": 0.0254, "ft": 0.3048, "yd": 0.9144, "mi": 1609.344,
    },
    "무게(기준 kg)": {
        "mg": 1e-6, "g": 0.001, "kg": 1.0, "t": 1000.0,
        "oz": 0.028349523125, "lb": 0.45359237,
    },
    "부피(기준 l)": {
        "ml": 0.001, "l": 1.0,
        "floz": 0.0295735295625, "cup": 0.2365882365, "gal": 3.785411784,  # US 단위
    },
    "시간(기준 s)": {
        "s": 1.0, "min": 60.0, "h": 3600.0, "d": 86400.0, "week": 604800.0,
    },
}

# 온도는 배율이 아니라 섭씨를 거쳐 변환
TEMP = "온도"
_TO_C = {
    "c": lambda v: v,
    "f": lambda v: (v - 32) * 5 / 9,
    "k": lambda v: v - 273.15,
}
_FROM_C = {
    "c": lambda v: v,
    "f": lambda v: v * 9 / 5 + 32,
    "k": lambda v: v + 273.15,
}

_CATEGORY_OF: dict[str, str] = {u: cat for cat, units in LINEAR.items() for u in units}
_CATEGORY_OF.update({u: TEMP for u in _TO_C})


def _norm(unit: str) -> str:
    """대소문자·공백·'°' 기호를 무시한다 (예: '°C' -> 'c')."""
    return unit.strip().lower().lstrip("°")


def convert(value: float, src: str, dst: str) -> float:
    s, d = _norm(src), _norm(dst)
    for u in (s, d):
        if u not in _CATEGORY_OF:
            raise ValueError(f"알 수 없는 단위: '{u}' (--list로 지원 단위 확인)")
    if _CATEGORY_OF[s] != _CATEGORY_OF[d]:
        raise ValueError(
            f"카테고리가 달라 변환할 수 없음: {s}({_CATEGORY_OF[s]}) -> {d}({_CATEGORY_OF[d]})"
        )

    cat = _CATEGORY_OF[s]
    if cat == TEMP:
        celsius = _TO_C[s](value)
        if celsius < -273.15 - 1e-9:
            raise ValueError("절대영도(-273.15°C) 미만의 온도는 변환할 수 없음")
        return _FROM_C[d](celsius)

    units = LINEAR[cat]
    return value * units[s] / units[d]


def _list_units() -> str:
    lines = [f"{cat}: {', '.join(units)}" for cat, units in LINEAR.items()]
    lines.append(f"{TEMP}: {', '.join(_TO_C)}")
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    p = argparse.ArgumentParser(description="단위 변환기")
    p.add_argument("value", nargs="?", type=float, help="변환할 값")
    p.add_argument("src", nargs="?", help="원래 단위")
    p.add_argument("dst", nargs="?", help="목표 단위")
    p.add_argument("--list", action="store_true", help="지원 단위 목록 출력")
    args = p.parse_args(argv)

    if args.list:
        print(_list_units())
        return 0
    if args.value is None or not args.src or not args.dst:
        p.error("사용법: unit_converter.py <값> <원래단위> <목표단위>")

    try:
        result = convert(args.value, args.src, args.dst)
    except ValueError as e:
        print(f"오류: {e}", file=sys.stderr)
        return 1

    print(f"{args.value:g} {args.src} = {result:.10g} {args.dst}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

**`test_unit_converter.py`**

```python
import unittest

from unit_converter import LINEAR, _TO_C, convert, main


class ConvertTest(unittest.TestCase):
    def test_length(self):
        self.assertAlmostEqual(convert(1, "km", "m"), 1000)
        self.assertAlmostEqual(convert(1, "mi", "km"), 1.609344)
        self.assertAlmostEqual(convert(12, "in", "ft"), 1)

    def test_mass_volume_time(self):
        self.assertAlmostEqual(convert(1, "lb", "g"), 453.59237)
        self.assertAlmostEqual(convert(1, "gal", "l"), 3.785411784)
        self.assertAlmostEqual(convert(1, "h", "min"), 60)

    def test_temperature(self):
        self.assertAlmostEqual(convert(100, "c", "f"), 212)
        self.assertAlmostEqual(convert(32, "f", "c"), 0)
        self.assertAlmostEqual(convert(0, "k", "c"), -273.15)

    def test_normalization(self):
        self.assertAlmostEqual(convert(100, "°C", "F"), 212)
        self.assertAlmostEqual(convert(1, "KM", "M"), 1000)

    def test_roundtrip_all_pairs(self):
        for units in LINEAR.values():
            for a in units:
                for b in units:
                    self.assertAlmostEqual(convert(convert(7.5, a, b), b, a), 7.5)
        for a in _TO_C:
            for b in _TO_C:
                self.assertAlmostEqual(convert(convert(25, a, b), b, a), 25)

    def test_errors(self):
        with self.assertRaises(ValueError):
            convert(1, "km", "kg")        # 카테고리 불일치
        with self.assertRaises(ValueError):
            convert(1, "foo", "m")        # 미지원 단위
        with self.assertRaises(ValueError):
            convert(-1, "k", "c")         # 절대영도 미만

    def test_cli(self):
        self.assertEqual(main(["10", "km", "mi"]), 0)
        self.assertEqual(main(["--list"]), 0)
        self.assertEqual(main(["1", "km", "kg"]), 1)


if __name__ == "__main__":
    unittest.main()
```

