    function render() {
      remainingEl.textContent = attemptsLeft;
      historyEl.textContent = guesses.length
        ? "입력한 숫자: " + guesses.join(", ")
        : "";
    }

    function setFeedback(message, cls) {
      feedback.textContent = message;
      feedback.className = cls;
    }

    function endGame() {
      finished = true;
      input.disabled = true;
      submitBtn.disabled = true;
    }

