// src/utils/money.ts
// 모든 금액은 "원 단위 정수"로 다룬다. (소수 금액은 허용하지 않음)

export type RoundingMode = 'round' | 'floor' | 'ceil' | 'trunc';

function assertInt(n: number, name = 'amount'): void {
  if (!Number.isSafeInteger(n)) {
    throw new Error(`${name}는 안전한 정수여야 합니다: ${n}`);
  }
}

/** 부동소수 잔여 오차 제거 (1100.0000000000002 → 1100) */
function clean(x: number): number {
  return Number(x.toPrecision(15));
}

/** 반올림 모드 적용. 'round'는 half away from zero. */
export function applyRound(x: number, mode: RoundingMode = 'round'): number {
  const v = clean(x);
  switch (mode) {
    case 'floor': return Math.floor(v);
    case 'ceil':  return Math.ceil(v);
    case 'trunc': return Math.trunc(v);
    case 'round': return Math.sign(v) * Math.round(Math.abs(v));
  }
}

/** 단위 처리: roundToUnit(12345, 10, 'floor') → 12340 (10원 미만 절사) */
export function roundToUnit(
  amount: number,
  unit = 10,
  mode: RoundingMode = 'floor',
): number {
  assertInt(amount);
  if (!Number.isInteger(unit) || unit <= 0) throw new Error(`unit이 올바르지 않습니다: ${unit}`);
  return applyRound(amount / unit, mode) * unit;
}

/** 금액의 퍼센트: percentOf(15000, 3.3, 'floor') → 495 */
export function percentOf(
  amount: number,
  percent: number,
  mode: RoundingMode = 'round',
): number {
  assertInt(amount);
  return applyRound((amount * percent) / 100, mode);
}

export function sum(values: number[]): number {
  values.forEach((v) => assertInt(v, 'value'));
  return values.reduce((a, b) => a + b, 0);
}

/** 공급가액 → 부가세 가산. 기본 세율 10%, 세액 절사. */
export function addVat(supply: number, rate = 10, mode: RoundingMode = 'floor') {
  const vat = percentOf(supply, rate, mode);
  return { supply, vat, total: supply + vat };
}

/** 합계(VAT 포함) → 공급가액·세액 분리. 공급가액 반올림, 세액 = 합계 − 공급가액. */
export function splitVat(total: number, rate = 10, mode: RoundingMode = 'round') {
  assertInt(total, 'total');
  const supply = applyRound((total * 100) / (100 + rate), mode);
  return { supply, vat: total - supply, total };
}

/**
 * 비율대로 분배하되 합계를 정확히 보존 (최대 잔여 방식, 동률이면 앞 순번 우선).
 * allocate(10000, [1, 2]) → [3333, 6667]
 */
export function allocate(amount: number, ratios: number[]): number[] {
  assertInt(amount);
  if (ratios.length === 0 || ratios.some((r) => !(r >= 0))) {
    throw new Error('ratios는 0 이상 숫자의 비어 있지 않은 배열이어야 합니다');
  }
  const total = ratios.reduce((a, b) => a + b, 0);
  if (total <= 0) throw new Error('ratios의 합은 0보다 커야 합니다');

  const sign = amount < 0 ? -1 : 1;
  const abs = Math.abs(amount);
  const raw = ratios.map((r) => (abs * r) / total);
  const base = raw.map(Math.floor);
  const rest = abs - base.reduce((a, b) => a + b, 0);

  const order = raw
    .map((v, i) => ({ i, frac: v - base[i] }))
    .sort((a, b) => b.frac - a.frac || a.i - b.i);
  for (let k = 0; k < rest; k++) base[order[k].i] += 1;

  return base.map((v) => (v === 0 ? 0 : sign * v));
}

/** n등분 (나머지는 앞사람부터 1원씩): splitEvenly(100, 3) → [34, 33, 33] */
export function splitEvenly(amount: number, n: number): number[] {
  if (!Number.isInteger(n) || n <= 0) throw new Error(`n이 올바르지 않습니다: ${n}`);
  return allocate(amount, Array(n).fill(1));
}

/** 1234567 → "1,234,567원" */
export function formatWon(amount: number): string {
  assertInt(amount);
  return `${amount.toLocaleString('ko-KR')}원`;
}

/** 123456789 → "1억 2,345만 6,789원" */
export function formatKoreanUnit(amount: number): string {
  assertInt(amount);
  if (amount === 0) return '0원';
  const sign = amount < 0 ? '-' : '';
  let rest = Math.abs(amount);
  const parts: string[] = [];
  for (const [unit, label] of [[1e12, '조'], [1e8, '억'], [1e4, '만']] as const) {
    const q = Math.floor(rest / unit);
    if (q > 0) {
      parts.push(`${q.toLocaleString('ko-KR')}${label}`);
      rest -= q * unit;
    }
  }
  if (rest > 0) parts.push(rest.toLocaleString('ko-KR'));
  return `${sign}${parts.join(' ')}원`;
}

/** "1,234원", "₩1,234", "-1,234" → 숫자. 형식이 맞지 않으면 에러. */
export function parseWon(input: string): number {
  const cleaned = input.replace(/[₩원,\s]/g, '');
  if (!/^-?\d+$/.test(cleaned)) throw new Error(`금액 형식이 올바르지 않습니다: ${input}`);
  const n = Number(cleaned);
  assertInt(n, 'parsed');
  return n;
}
```

