#!/usr/bin/env python3
"""html2md - HTML을 Markdown으로 변환하는 독립 실행형 도구 (표준 라이브러리만 사용)."""
from __future__ import annotations

import argparse
import re
import sys
from html.parser import HTMLParser

_VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input",
         "link", "meta", "source", "track", "wbr"}
_P_CLOSERS = {"address", "article", "aside", "blockquote", "div", "dl",
              "fieldset", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6",
              "header", "hr", "main", "nav", "ol", "p", "pre", "section",
              "table", "ul"}
_SKIP = {"script", "style", "head", "noscript", "template"}
_HEADINGS = {"h1": 1, "h2": 2, "h3": 3, "h4": 4, "h5": 5, "h6": 6}
_CONTAINERS = {"html", "body", "div", "section", "article", "header", "footer",
               "main", "nav", "aside", "figure", "figcaption", "form", "address",
               "details", "summary", "fieldset", "dl", "dt", "dd", "table",
               "thead", "tbody", "tfoot", "tr", "td", "th", "caption"}
_ESCAPE = re.compile(r"([\\`*_\[\]<])")

# 내부 제어 문자: \x00\n = 강제 줄바꿈(<br>), \x02 = 코드 블록 안의 보호된 줄바꿈
_HARD_BREAK = "\x00\n"
_CODE_NL = "\x02"


# ---------------------------------------------------------------- 파싱
class _Node:
    __slots__ = ("tag", "attrs", "children")

    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = {k: (v or "") for k, v in (attrs or [])}
        self.children: list = []


class _TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node("#root")
        self.stack = [self.root]

    def _close_p(self):
        if self.stack[-1].tag == "p":
            self.stack.pop()

    def _close_open_li(self):
        for i in range(len(self.stack) - 1, 0, -1):
            tag = self.stack[i].tag
            if tag in ("ul", "ol"):
                return
            if tag == "li":
                del self.stack[i:]
                return

    def handle_starttag(self, tag, attrs):
        if tag == "li":
            self._close_open_li()
        if tag in _P_CLOSERS:
            self._close_p()
        node = _Node(tag, attrs)
        self.stack[-1].children.append(node)
        if tag not in _VOID:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.stack[-1].children.append(_Node(tag, attrs))

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        kids = self.stack[-1].children
        if kids and isinstance(kids[-1], str):
            kids[-1] += data
        else:
            kids.append(data)


# ---------------------------------------------------------------- 렌더링 helper
def _escape(text: str) -> str:
    return _ESCAPE.sub(r"\\\1", text)


def _text_of(node) -> str:
    if isinstance(node, str):
        return node
    if node.tag == "br":
        return "\n"
    return "".join(_text_of(c) for c in node.children)


def _split_ws(s: str):
    core = s.strip()
    if not core:
        return s, "", ""
    lead = s[: len(s) - len(s.lstrip())]
    trail = s[len(s.rstrip()):]
    return lead, core, trail


def _wrap(content: str, before: str, after: str) -> str:
    lead, core, trail = _split_ws(content)
    if not core:
        return content
    return f"{lead}{before}{core}{after}{trail}"


def _inline(node) -> str:
    s = _render_children(node)
    s = re.sub(r"[ \t]*\n[ \t]*", "\n", s)
    return s.strip()


def _oneline(node) -> str:
    return re.sub(r"\x00?\n", " ", _inline(node)).strip()


def _url(href: str) -> str:
    return href.replace(" ", "%20").replace("(", "%28").replace(")", "%29")


def _title(attrs) -> str:
    t = attrs.get("title", "").strip()
    if not t:
        return ""
    t = t.replace('"', '\\"')
    return f' "{t}"'


def _code_span(text: str) -> str:
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return ""
    longest = max((len(m) for m in re.findall(r"`+", text)), default=0)
    fence = "`" * (longest + 1)
    pad = " " if text.startswith("`") or text.endswith("`") else ""
    return f"{fence}{pad}{text}{pad}{fence}"


def _render_pre(node) -> str:
    lang = ""
    for c in node.children:
        if not isinstance(c, str) and c.tag == "code":
            for cls in c.attrs.get("class", "").split():
                m = re.match(r"(?:language|lang)-(\S+)", cls)
                if m:
                    lang = m.group(1)
                    break
    text = "".join(_text_of(c) for c in node.children)
    if text.startswith("\n"):
        text = text[1:]
    text = text.rstrip("\n")
    longest = max((len(m) for m in re.findall(r"`{3,}", text)), default=2)
    fence = "`" * max(3, longest + 1)
    body = text.replace("\n", _CODE_NL)
    return f"\n\n{fence}{lang}\n{body}\n{fence}\n\n"


def _render_list(node) -> str:
    ordered = node.tag == "ol"
    number = 1
    if ordered:
        try:
            number = int(node.attrs.get("start", "1"))
        except ValueError:
            number = 1
    items = []
    for child in node.children:
        if isinstance(child, str) or child.tag != "li":
            continue
        marker = f"{number}. " if ordered else "- "
        number += 1
        body = _render_children(child).strip()
        body = re.sub(r"[ \t]*\n(?:[ \t]*\n)+", "\n", body)
        indent = " " * len(marker)
        body = body.replace("\n", "\n" + indent).replace(_CODE_NL, _CODE_NL + indent)
        items.append(marker + body)
    if not items:
        return ""
    return "\n\n" + "\n".join(items) + "\n\n"


def _render_blockquote(node) -> str:
    body = _render_children(node).strip()
    if not body:
        return ""
    body = re.sub(r"[ \t]+\n", "\n", body)
    body = re.sub(r"\n{3,}", "\n\n", body)
    quoted = "\n".join(("> " + ln) if ln.strip() else ">" for ln in body.split("\n"))
    quoted = quoted.replace(_CODE_NL, _CODE_NL + "> ")
    return "\n\n" + quoted + "\n\n"


def _render_children(node) -> str:
    out = ""
    for child in node.children:
        s = _render(child)
        if isinstance(child, str) and (out == "" or out.endswith(("\n", " "))):
            s = s.lstrip(" ")
        out += s
    return out


def _render(node) -> str:
    if isinstance(node, str):
        return _escape(re.sub(r"\s+", " ", node))
    tag = node.tag
    if tag in _SKIP:
        return ""
    if tag in _HEADINGS:
        text = _oneline(node)
        return f"\n\n{'#' * _HEADINGS[tag]} {text}\n\n" if text else ""
    if tag == "p":
        text = _inline(node)
        return f"\n\n{text}\n\n" if text else ""
    if tag in _CONTAINERS:
        body = _render_children(node).strip()
        return f"\n\n{body}\n\n" if body else ""
    if tag == "br":
        return _HARD_BREAK
    if tag == "hr":
        return "\n\n---\n\n"
    if tag in ("strong", "b"):
        return _wrap(_render_children(node), "**", "**")
    if tag in ("em", "i"):
        return _wrap(_render_children(node), "*", "*")
    if tag in ("del", "s", "strike"):
        return _wrap(_render_children(node), "~~", "~~")
    if tag == "code":
        return _code_span(_text_of(node))
    if tag == "pre":
        return _render_pre(node)
    if tag == "a":
        content = _render_children(node)
        href = node.attrs.get("href", "").strip()
        if not href:
            return content
        lead, core, trail = _split_ws(content)
        core = re.sub(r"\x00?\n", " ", core) or href
        return f"{lead}[{core}]({_url(href)}{_title(node.attrs)}){trail}"
    if tag == "img":
        src = node.attrs.get("src", "").strip()
        alt = _escape(re.sub(r"\s+", " ", node.attrs.get("alt", "")).strip())
        if not src:
            return alt
        return f"![{alt}]({_url(src)}{_title(node.attrs)})"
    if tag in ("ul", "ol"):
        return _render_list(node)
    if tag == "blockquote":
        return _render_blockquote(node)
    return _render_children(node)  # span 등 알 수 없는 태그는 내용만 통과


# ---------------------------------------------------------------- 공개 API
def convert(html: str) -> str:
    builder = _TreeBuilder()
    builder.feed(html)
    builder.close()
    text = _render_children(builder.root)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    text = re.sub(r" *\x00\n", "  \n", text)
    text = text.replace("\x00", "").replace(_CODE_NL, "\n")
    text = text.strip()
    return text + "\n" if text else ""


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="HTML을 Markdown으로 변환합니다.")
    ap.add_argument("input", nargs="?", default="-",
                    help="입력 HTML 파일 (기본: stdin, '-')")
    ap.add_argument("-o", "--output", help="출력 파일 (기본: stdout)")
    args = ap.parse_args(argv)

    if args.input == "-":
        html = sys.stdin.read()
    else:
        with open(args.input, encoding="utf-8") as f:
            html = f.read()

    md = convert(html)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as f:
            f.write(md)
    else:
        sys.stdout.write(md)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

