        self.assertEqual(convert(html), "- 사과\n  - 부사\n  - 홍옥\n- 배\n")

    def test_ordered_list_start(self):
        self.assertEqual(convert('<ol start="3"><li>a</li><li>b</li></ol>'), "3. a\n4. b\n")

    def test_link_and_image(self):
        html = '<p><a href="https://example.com" title="예시">링크</a> <img src="a.png" alt="그림"></p>'
        self.assertEqual(convert(html), '[링크](https://example.com "예시") ![그림](a.png)\n')

    def test_code_block(self):
        html = '<pre><code class="language-python">def f():\n    return 1\n</code></pre>'
        self.assertEqual(convert(html), "```python\ndef f():\n    return 1\n```\n")

    def test_quote_hr_br(self):
        html = "<blockquote><p>인용문</p></blockquote><hr><p>첫 줄<br>둘째 줄</p>"
        self.assertEqual(convert(html), "> 인용문\n\n---\n\n첫 줄  \n둘째 줄\n")

    def test_escape_and_skip(self):
        html = "<p>2 * 3 = 6 and snake_case</p><script>alert(1)</script>"
        self.assertEqual(convert(html), "2 \\* 3 = 6 and snake\\_case\n")

    def test_implicit_li_close_and_empty(self):
        self.assertEqual(convert("<ul><li>a<li>b</ul>"), "- a\n- b\n")
        self.assertEqual(convert(""), "")


