이 환경에서는 파일 생성과 실행이 안 되므로, 아래 코드를 `html2md.py`로 저장해 쓰시면 됩니다.

```python
#!/usr/bin/env python3
"""html2md.py — HTML을 Markdown으로 변환하는 CLI (표준 라이브러리만 사용)."""
import argparse
import re
import sys
from html.parser import HTMLParser

VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input",
        "link", "meta", "source", "track", "wbr"}
SKIP = {"script", "style", "head", "title", "noscript", "template", "svg"}
CLOSES = {"li": {"li"}, "p": {"p"}, "td": {"td", "th"},
          "th": {"td", "th"}, "tr": {"td", "th", "tr"}}
HEADINGS = {f"h{i}" for i in range(1, 7)}
BLOCK = HEADINGS | {
    "html", "body", "div", "section", "article", "main", "header", "footer",
    "nav", "aside", "figure", "figcaption", "form", "fieldset", "details",
    "summary", "address", "dl", "dt", "dd", "p", "ul", "ol", "blockquote",
    "pre", "hr", "table",
}
WS = re.compile(r"\s+")
BR = "\x00"  # <br> 임시 표식


# ---------- HTML → 트리 ----------
class Node:
    __slots__ = ("tag", "attrs", "children")

    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = {k: v or "" for k, v in (attrs or [])}
        self.children = []


class TreeBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node("#root")
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        while self.stack[-1].tag in CLOSES.get(tag, ()):
            self.stack.pop()
        node = Node(tag, attrs)
        self.stack[-1].children.append(node)
        if tag not in VOID:
            self.stack.append(node)

    def handle_endtag(self, tag):
        if tag in VOID:
            return
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data.replace("\x00", ""))


# ---------- 인라인 ----------
def escape(s):
    s = re.sub(r"([\\`*])", r"\\\1", s)
    return re.sub(r"(?<!\w)_|_(?!\w)", r"\\_", s)


def url(u):
    return u.strip().replace(" ", "%20").replace("(", "%28").replace(")", "%29")


def text_of(n):
    if isinstance(n, str):
        return n
    if n.tag in SKIP:
        return ""
    if n.tag == "br":
        return "\n"
    return "".join(text_of(c) for c in n.children)


def wrap(marker, inner):
    core = inner.strip()
    if not core:
        return inner
    lead = inner[: len(inner) - len(inner.lstrip())]
    trail = inner[len(inner.rstrip()):]
    return f"{lead}{marker}{core}{marker}{trail}"


def code_span(text):
    text = WS.sub(" ", text).strip()
    if not text:
        return ""
    fence = "`" * (max((len(m) for m in re.findall(r"`+", text)), default=0) + 1)
    pad = " " if text.startswith("`") or text.endswith("`") else ""
    return f"{fence}{pad}{text}{pad}{fence}"


def inline_children(n):
    return "".join(inline(c) for c in n.children)


def inline(n):
    if isinstance(n, str):
        return escape(WS.sub(" ", n))
    t = n.tag
    if t in SKIP:
        return ""
    if t == "br":
        return BR
    if t == "img":
        src = n.attrs.get("src")
        return f"![{n.attrs.get('alt', '')}]({url(src)})" if src else ""
    if t == "code":
        return code_span(text_of(n))
    inner = inline_children(n)
    if t in ("strong", "b"):
        return wrap("**", inner)
    if t in ("em", "i"):
        return wrap("*", inner)
    if t in ("del", "s", "strike"):
        return wrap("~~", inner)
    if t == "a":
        href = n.attrs.get("href")
        return f"[{inner.strip()}]({url(href)})" if href and inner.strip() else inner
    if t in BLOCK:  # 인라인 안에 낀 블록 요소는 공백으로 펼침
        return f" {inner} "
    return inner


def finish(s, br="  \n"):
    s = re.sub(r" {2,}", " ", s)
    s = re.sub(r" *\x00 *", "\x00", s)
    return s.replace("\x00", br).strip()


# ---------- 블록 ----------
def fenced(n):
    text = text_of(n).strip("\n")
    lang = ""
    for c in n.children:
        if not isinstance(c, str) and c.tag == "code":
            m = re.search(r"(?:language|lang)-([\w+-]+)", c.attrs.get("class", ""))
            lang = m.group(1) if m else ""
    fence = "`" * max(3, max((len(m) for m in re.findall(r"`+", text)), default=0) + 1)
    return f"{fence}{lang}\n{text}\n{fence}"


def md_list(n, indent):
    ordered = n.tag == "ol"
    try:
        num = int(n.attrs.get("start") or 1)
    except ValueError:
        num = 1
    lines = []
    for li in n.children:
        if isinstance(li, str) or li.tag != "li":
            continue
        marker = f"{num}. " if ordered else "- "
        num += 1
        buf, nested = [], []
        for ch in li.children:
            if not isinstance(ch, str) and ch.tag in ("ul", "ol"):
                nested.append(md_list(ch, indent + " " * len(marker)))
            else:
                buf.append(inline(ch))
        lines.append(f"{indent}{marker}{finish(''.join(buf), ' ')}".rstrip())
        lines.extend(s for s in nested if s)
    return "\n".join(lines)


def md_table(n):
    rows = []

    def collect(node):
        for c in node.children:
            if isinstance(c, str):
                continue
            if c.tag == "tr":
                rows.append([
                    finish(inline_children(cell), " ").replace("|", "\\|")
                    for cell in c.children
                    if not isinstance(cell, str) and cell.tag in ("td", "th")
                ])
            elif c.tag in ("thead", "tbody", "tfoot"):
                collect(c)

    collect(n)
    rows = [r for r in rows if r]
    if not rows:
        return ""
    width = max(map(len, rows))
    rows = [r + [""] * (width - len(r)) for r in rows]
    fmt = lambda r: "| " + " | ".join(r) + " |"
    return "\n".join([fmt(rows[0]), fmt(["---"] * width), *map(fmt, rows[1:])])


def block(n):
    t = n.tag
    if t in HEADINGS:
        text = finish(inline_children(n), " ")
        return [f"{'#' * int(t[1])} {text}"] if text else []
    if t == "p":
        text = finish(inline_children(n))
        return [text] if text else []
    if t == "hr":
        return ["---"]
    if t == "pre":
        return [fenced(n)]
    if t == "blockquote":
        inner = "\n\n".join(blocks(n.children))
        if not inner:
            return []
        return ["\n".join("> " + l if l else ">" for l in inner.split("\n"))]
    if t in ("ul", "ol"):
        s = md_list(n, "")
        return [s] if s else []
    if t == "table":
        s = md_table(n)
        return [s] if s else []
    return blocks(n.children)  # div, section 등 컨테이너


def blocks(children):
    out, buf = [], []

    def flush():
        text = finish("".join(buf))
        buf.clear()
        if text:
            out.append(text)

    for ch in children:
        if isinstance(ch, str) or ch.tag not in BLOCK:
            buf.append(inline(ch))
        else:
            flush()
            out.extend(block(ch))
    flush()
    return out


# ---------- 진입점 ----------
def convert(html):
    parser = TreeBuilder()
    parser.feed(html)
    parser.close()
    return "\n\n".join(blocks(parser.root.children)) + "\n"


def main(argv=None):
    ap = argparse.ArgumentParser(description="HTML → Markdown 변환기")
    ap.add_argument("input", nargs="?", default="-", help="입력 HTML 파일 (기본: stdin)")
    ap.add_argument("-o", "--output", help="출력 .md 파일 (기본: stdout)")
    args = ap.parse_args(argv)

    if args.input == "-":
        html = sys.stdin.read()
    else:
        with open(args.input, encoding="utf-8", errors="replace") as f:
            html = f.read()

    md = convert(html)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as f:
            f.write(md)
    else:
        sys.stdout.write(md)


if __name__ == "__main__":
    main()
```

